select

from pa_view_deposit_module_org

    and org_code = #{orgCode }
    and customer_type = #{customerType }
    and save_ftp = #{saveFtp }
    and save_balance = #{saveBalance }
    and save_balance_last_month =
        #{saveBalanceLastMonth }

    and save_balance_begin_year =
        #{saveBalanceBeginYear }

    and save_day_avg = #{saveDayAvg }
    and save_day_avg_last_month =
        #{saveDayAvgLastMonth }

    and save_day_avg_begin_year =
        #{saveDayAvgBeginYear }

    and deposit_save_balance =
        #{depositSaveBalance }

    and
        deposit_save_balance_last_month = #{depositSaveBalanceLastMonth }

    and
        deposit_save_balance_begin_year = #{depositSaveBalanceBeginYear }

    and deposit_save_day_avg =
        #{depositSaveDayAvg }

    and
        deposit_save_day_avg_last_month = #{depositSaveDayAvgLastMonth }

    and
        deposit_save_day_avg_begin_year = #{depositSaveDayAvgBeginYear }

    and create_time = #{createTime }
    and update_time = #{updateTime }

select

from pa_view_deposit_module_org

    and grid_code = #{gridCode }
    and customer_type = #{customerType }

        and org_code = #{orgCodes}
